Wait Hold on  it kinda is 
 rspack/react-refresh complies that inline hook into shit like 
`[hookName]: _s(() => {
  _s();
  const value = useContext(Context);
  ...
}, "ksutO2/...")`

you end up with an anonymous arrow inside an anonymous  _s wrapper. Devtools is label is hooking with the outer function name so you get diddly you get the fallback here  (createRequiredContext)
Since your caller is invoking the _swrapper define property on the inner function does not help here either (Which is what dev tool sees)

My fix is pull the hook out the returned object  assign it to a var then name that var before returning it 

```
`const hook = () => {
  const value = useContext(Context);
  if (value === moContextValueSymbol) {
    throw new Error(`No ${Context.displayName} value was provided`);
  }
  return value;
};

Object.defineProperty(hook, 'name', {
  value: hookName,
  configurable: true,
});

return {
  [providerName]: Context.Provider,
  [hookName]: hook,
};`
```

so react refresh returns it like this at runtime

```
const hook = _s(() => { _s(); ... }, "sig");
Object.defineProperty(hook, 'name', { value: 'useReactExample' });
return { useReactExample: hook };
```

Attaching the Code snippet with comments for Your convenience


```
import { createContext, type Provider, useContext } from 'react';
import { createRoot } from 'react-dom/client';

// Sentinel value so "no provider" is distinguishable from a real context value.
const moContextValueSymbol = Symbol('no-context-value');

function createRequiredContext<T>() {
  return <Name extends string>(
    name: string extends Name ? never : Name
  ): {
    [K in `${Name}Provider`]: Provider<T>;
  } & {
    [K in `use${Name}`]: () => T;
  } => {
    const providerName = `${name as Name}Provider` as const;
    const hookName = `use${name as Name}` as const;

    const Context = createContext<T | typeof moContextValueSymbol>(
      moContextValueSymbol
    );
    Context.displayName = `${name}Context`;

    // IMPORTANT: Do not define the hook inline in the returned object, e.g.
    //   [hookName]: () => useContext(Context)
    //
    // react-refresh/rspack compiles that into:
    //   [hookName]: _s(() => { _s(); ... }, "sig")
    //
    // That creates an anonymous arrow wrapped by an anonymous _s() wrapper.
    // React DevTools reads the outer wrapper's Function.name, so you get "" and
    // a cryptic identifier like "createRequiredContext/</<".
    const hook = () => {
      const value = useContext(Context);
      if (value === moContextValueSymbol) {
        throw new Error(`No ${Context.displayName} value was provided`);
      }
      return value;
    };

    // At runtime this becomes:
    //   const hook = _s(() => { _s(); ... }, "sig");
    //   Object.defineProperty(hook, 'name', { value: hookName });
    //
    // So we name the _s wrapper — the function callers actually invoke —
    // not the inner arrow function.
    Object.defineProperty(hook, 'name', {
      value: hookName,
      configurable: true,
    });

    return {
      [providerName]: Context.Provider as Provider<T>,
      [hookName]: hook,
    } as any;
  };
}

const { ReactExampleProvider, useReactExample } =
  createRequiredContext<number>()('ReactExample');

// Same issue applies outside React: computed key + arrow => anonymous function.
const hookName = 'useVanillaExample';
const useVanillaExample = (() => {}) as () => void;
Object.defineProperty(useVanillaExample, 'name', {
  value: hookName,
  configurable: true,
});

const Parent = () => (
  <ReactExampleProvider value={123}>
    <Child />
  </ReactExampleProvider>
);
const Child = () => `Context value: ${useReactExample()}`;

createRoot(document.getElementById('root')!).render(
  <pre>
    {<Parent />}
    {'\n\n'}
    useReactExample.name === "{useReactExample.name}"{'\n'}
    useVanillaExample.name === "{useVanillaExample.name}"
  </pre>
);

// Expected:
// - useReactExample.name === "useReactExample"
// - useVanillaExample.name === "useVanillaExample"
// - React DevTools shows "ReactExample" for the hook in Child
//   (DevTools strips the "use" prefix from custom hook names)
```
